package com.itangcent.easyapi.core.standalone

import com.itangcent.easyapi.headless.core.PreviewArtifact
import com.itangcent.easyapi.headless.core.PreviewEndpoint
import java.nio.file.Files
import java.nio.file.Path

/** Renders a self-contained, static API tree and detail view for CI artifacts. */
object ApiPreviewRenderer {
    /** Renders already-serialized data without coupling the renderer to PSI. */
    fun renderModel(endpoints: List<PreviewEndpoint>, output: Path, wrapResponses: Boolean = false): PreviewArtifact {
        require(!Files.exists(output)) { "Preview output already exists: $output" }
        Files.createDirectories(output)
        val items = endpoints.mapIndexed { index, endpoint ->
            PreviewItem(index, endpoint.group, endpoint.title, endpoint.method, endpoint.path, buildDetail(endpoint, wrapResponses))
        }
        val groups = items.groupBy { it.group }.toSortedMap()
        val tree = groups.entries.joinToString("\n") { (group, groupItems) ->
            """<details class="tree-group" open>
                <summary><span class="folder-icon" aria-hidden="true">${folderIcon()}</span><span class="group-name">${escape(group)}</span><span class="count">${groupItems.size}</span></summary>
                <div class="endpoint-list">${groupItems.joinToString("\n") { item ->
                    """<button class="endpoint-item" data-id="${item.id}" data-search="${escape("${item.title} ${item.method} ${item.path} ${item.group}")}" type="button">
                        <span class="method method-${item.method.lowercase()}">${escape(item.method)}</span>
                        <span class="endpoint-copy"><span class="endpoint-title">${escape(item.title)}</span><span class="endpoint-path">${escape(item.path)}</span></span>
                    </button>"""
                }}</div>
            </details>"""
        }
        val details = items.joinToString("\n") { item -> "<article id=\"detail-${item.id}\" class=\"detail-view\">${item.detail}</article>" }
        val generatedAt = java.time.OffsetDateTime.now().toString()
        val indexFile = output.resolve("index.html")
        Files.writeString(indexFile, """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>EasyYapi API Preview</title>
<style>
:root{color-scheme:light;--ink:#172033;--muted:#667085;--line:#e4e7ec;--surface:#fff;--soft:#f7f8fa;--sidebar:#111827;--sidebar-2:#1a2435;--sidebar-text:#dbe4f0;--accent:#2563eb;--green:#059669;--red:#dc2626;--shadow:0 12px 30px rgba(16,24,40,.08)}
html.dark{color-scheme:dark;--ink:#e5edf8;--muted:#9aa9bc;--line:#2d3a4d;--surface:#172235;--soft:#101827;--accent:#7db4ff;--shadow:0 12px 30px rgba(0,0,0,.2)}html.dark .topbar{background:rgba(23,34,53,.9)}html.dark th{background:#202d41;color:#b8c7d9}html.dark .empty{background:#172235;border-color:#40516a}html.dark .stat{background:#172235}html.dark .route-path{color:#e5edf8}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--soft)}body{display:grid;grid-template-columns:340px minmax(0,1fr);min-height:100vh}button,input{font:inherit}button{cursor:pointer}
.sidebar{display:flex;flex-direction:column;min-width:0;background:var(--sidebar);color:var(--sidebar-text);border-right:1px solid #253047}.brand{padding:24px 22px 18px;border-bottom:1px solid #283449}.brand-row{display:flex;align-items:center;gap:10px}.brand-mark{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,#60a5fa,#2563eb);color:#fff;font-weight:800;box-shadow:0 5px 16px rgba(37,99,235,.35)}.brand h1{margin:0;font-size:17px;letter-spacing:-.02em;color:#fff}.brand p{margin:7px 0 0 40px;color:#93a4ba;font-size:12px}.search-wrap{padding:16px 18px 12px;position:relative}.search-icon{position:absolute;left:31px;top:27px;color:#8ea0b7;pointer-events:none}.search-wrap input{width:100%;height:40px;padding:0 38px;border:1px solid #34435c;border-radius:9px;outline:none;background:var(--sidebar-2);color:#fff}.search-wrap input::placeholder{color:#8ea0b7}.search-wrap input:focus{border-color:#60a5fa;box-shadow:0 0 0 3px rgba(96,165,250,.2)}.search-count{padding:0 20px 10px;color:#8ea0b7;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.tree{overflow:auto;padding:0 10px 24px;scrollbar-color:#35445b transparent}.tree-group{border-top:1px solid rgba(148,163,184,.1)}.tree-group summary{display:flex;align-items:center;gap:8px;min-height:43px;padding:0 10px;color:#e5edf8;list-style:none;cursor:pointer;font-size:12px;font-weight:650}.tree-group summary::-webkit-details-marker{display:none}.tree-group summary:focus-visible,.endpoint-item:focus-visible{outline:2px solid #60a5fa;outline-offset:-2px}.folder-icon{display:grid;place-items:center;color:#93c5fd}.group-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.count{min-width:22px;text-align:center;padding:2px 6px;border-radius:99px;background:#293750;color:#a9bad0;font-size:10px}.endpoint-list{padding:0 0 9px}.endpoint-item{display:flex;align-items:flex-start;gap:8px;width:100%;padding:9px 10px 9px 22px;border:0;border-left:2px solid transparent;text-align:left;background:transparent;color:#bfcbda;transition:background 180ms ease,border-color 180ms ease,color 180ms ease}.endpoint-item:hover{background:#1b2940;color:#fff}.endpoint-item.active{background:#1d3555;border-left-color:#60a5fa;color:#fff}.method{flex:0 0 47px;margin-top:1px;padding:3px 4px;border-radius:4px;text-align:center;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:9px;font-weight:700}.method-get{background:rgba(59,130,246,.16);color:#7db4ff}.method-post{background:rgba(16,185,129,.16);color:#6ee7b7}.method-put,.method-patch{background:rgba(245,158,11,.16);color:#fcd34d}.method-delete{background:rgba(239,68,68,.16);color:#fca5a5}.endpoint-copy{min-width:0;display:flex;flex-direction:column;gap:3px}.endpoint-title,.endpoint-path{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.endpoint-title{font-size:12px;line-height:1.35}.endpoint-path{font-family:"JetBrains Mono",ui-monospace,monospace;color:#8193aa;font-size:10px}.endpoint-item.active .endpoint-path{color:#aec9eb}
.content{min-width:0;overflow:auto}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 38px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.9);backdrop-filter:blur(10px);position:sticky;top:0;z-index:5}.eyebrow{margin:0 0 4px;color:var(--accent);font-size:11px;font-weight:750;letter-spacing:.11em;text-transform:uppercase}.topbar h2{margin:0;font-size:20px;letter-spacing:-.025em}.topbar-meta{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:12px}.status{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border:1px solid #a7f3d0;border-radius:99px;background:#ecfdf5;color:#047857;font-weight:650}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:#10b981}.icon-button{display:grid;place-items:center;width:36px;height:36px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--muted)}.icon-button:hover{background:var(--soft);color:var(--ink)}.icon-button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.main-inner{max-width:1120px;margin:0 auto;padding:34px 38px 64px}.hero{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:26px}.hero h3{margin:0;font-size:28px;letter-spacing:-.04em}.hero p{margin:8px 0 0;color:var(--muted);font-size:14px}.stats{display:flex;gap:9px;flex-wrap:wrap}.stat{padding:10px 13px;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:0 1px 2px rgba(16,24,40,.03)}.stat strong{display:block;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:16px}.stat span{display:block;margin-top:2px;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.detail-view{display:none}.detail-view.active{display:block;animation:fade-in 180ms ease}@keyframes fade-in{from{opacity:.4;transform:translateY(3px)}to{opacity:1;transform:none}}.detail-head{padding:24px 26px;border:1px solid var(--line);border-radius:12px 12px 0 0;background:var(--surface);box-shadow:var(--shadow)}.detail-head h3{margin:0;font-size:22px;letter-spacing:-.025em}.route{display:flex;align-items:center;gap:10px;margin:13px 0 0;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:13px;overflow-wrap:anywhere}.route-method{padding:5px 8px;border-radius:5px;font-size:11px;font-weight:750}.route-method.get{background:#dbeafe;color:#1d4ed8}.route-method.post{background:#d1fae5;color:#047857}.route-method.put,.route-method.patch{background:#fef3c7;color:#b45309}.route-method.delete{background:#fee2e2;color:#b91c1c}.route-path{color:var(--ink)}.description{margin:15px 0 0;color:var(--muted);line-height:1.6}.source{margin:17px 0 0;color:#98a2b3;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:11px;overflow-wrap:anywhere}.detail-body{padding:22px 26px;border:1px solid var(--line);border-top:0;border-radius:0 0 12px 12px;background:var(--surface)}.section{margin-top:22px}.section:first-child{margin-top:0}.section-title{display:flex;align-items:center;justify-content:space-between;margin:0 0 10px;font-size:13px;font-weight:750}.section-title span{color:var(--muted);font-size:11px;font-weight:500}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}table{width:100%;min-width:620px;border-collapse:collapse;font-size:12px}th,td{padding:11px 13px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:var(--soft);color:#475467;font-size:10px;text-transform:uppercase;letter-spacing:.07em}tr:last-child td{border-bottom:0}.required{color:var(--red);font-weight:700}.code-shell{position:relative;border:1px solid #202b3e;border-radius:9px;overflow:hidden;background:#0f172a}.code-label{display:flex;align-items:center;justify-content:space-between;padding:9px 13px;border-bottom:1px solid #26344a;color:#9fb0c7;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.copy-button{border:0;border-radius:5px;padding:5px 8px;background:#22324b;color:#c8d7e9;font-size:10px}.copy-button:hover{background:#304664;color:#fff}.copy-button:focus-visible{outline:2px solid #93c5fd;outline-offset:2px}.code-shell pre{margin:0;padding:16px;max-height:420px;overflow:auto;color:#d8e4f2;font-family:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;line-height:1.65;white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:14px;border:1px dashed #cbd5e1;border-radius:8px;background:#fafbfc;color:var(--muted);font-size:12px}.hidden{display:none!important}
@media(max-width:900px){body{display:block}.sidebar{max-height:48vh}.content{overflow:visible}.topbar{padding:16px 20px}.topbar-meta{font-size:11px}.main-inner{padding:24px 20px 48px}.hero{display:block}.stats{margin-top:18px}.detail-head,.detail-body{padding:20px}.brand{padding-top:18px}}
@media(max-width:560px){.topbar{align-items:flex-start}.topbar-meta .status{display:none}.topbar h2{font-size:17px}.hero h3{font-size:24px}.topbar{padding:14px 16px}.main-inner{padding:20px 14px 40px}.search-wrap{padding-left:14px;padding-right:14px}.search-count{padding-left:16px}.tree{padding-left:6px;padding-right:6px}.detail-head h3{font-size:19px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;transition-duration:.01ms!important}}
</style></head><body>
<aside class="sidebar" aria-label="API navigation"><div class="brand"><div class="brand-row"><div class="brand-mark" aria-hidden="true">E</div><h1>EasyYapi Preview</h1></div><p>Headless API documentation</p></div>
<div class="search-wrap"><span class="search-icon" aria-hidden="true">${searchIcon()}</span><input id="search" type="search" aria-label="Search API endpoints" placeholder="Search name, method, or URL…" autocomplete="off"></div>
<div id="search-count" class="search-count">${items.size} endpoints</div><nav id="tree" class="tree">$tree</nav></aside>
<main class="content" id="main-content" tabindex="-1"><header class="topbar"><div><p class="eyebrow">API Dashboard</p><h2>Service contract explorer</h2></div><div class="topbar-meta"><span class="status">Static preview</span><span>Generated ${escape(generatedAt)}</span><button id="theme-toggle" class="icon-button" type="button" aria-label="Toggle dark mode" title="Toggle dark mode">${moonIcon()}</button></div></header>
<div class="main-inner"><section class="hero"><div><h3>Explore your APIs</h3><p>Select an endpoint from the tree to inspect its contract and examples.</p></div><div class="stats"><div class="stat"><strong>${items.size}</strong><span>Endpoints</span></div><div class="stat"><strong>${groups.size}</strong><span>Groups</span></div></div></section>$details</div></main>
<script>
const endpointButtons=[...document.querySelectorAll('.endpoint-item')],details=[...document.querySelectorAll('.detail-view')],groups=[...document.querySelectorAll('.tree-group')],search=document.querySelector('#search'),count=document.querySelector('#search-count');
function show(id){endpointButtons.forEach(button=>button.classList.toggle('active',button.dataset.id===String(id)));details.forEach(detail=>detail.classList.toggle('active',detail.id==='detail-'+id));}
function filter(){const query=search.value.trim().toLowerCase();let visible=0;endpointButtons.forEach(button=>{const match=!query||button.dataset.search.toLowerCase().includes(query);button.classList.toggle('hidden',!match);if(match)visible++});groups.forEach(group=>{const hasVisible=group.querySelector('.endpoint-item:not(.hidden)');group.classList.toggle('hidden',!hasVisible);if(query&&hasVisible)group.open=true});count.textContent=query?visible+' matching endpoints':endpointButtons.length+' endpoints';const active=endpointButtons.find(button=>button.classList.contains('active')&&!button.classList.contains('hidden'));if(visible&&!active)show(endpointButtons.find(button=>!button.classList.contains('hidden')).dataset.id);}
endpointButtons.forEach(button=>button.addEventListener('click',()=>show(button.dataset.id)));search.addEventListener('input',filter);
document.querySelectorAll('.copy-button').forEach(button=>button.addEventListener('click',async()=>{const code=document.getElementById(button.dataset.copy).textContent;try{await navigator.clipboard.writeText(code);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1200)}catch(_){button.textContent='Select and copy'}}));
document.querySelector('#theme-toggle').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));if(endpointButtons.length)show(endpointButtons[0].dataset.id);
</script></body></html>""")
        return PreviewArtifact(indexFile, items.size, groups.size)
    }

    private fun buildDetail(endpoint: PreviewEndpoint, wrapResponses: Boolean): String = buildString {
        append("<div class=\"detail-head\"><h3>${escape(endpoint.title)}</h3><div class=\"route\"><span class=\"route-method ${endpoint.method.lowercase()}\">${escape(endpoint.method)}</span><span class=\"route-path\">${escape(endpoint.path)}</span></div>")
        endpoint.description?.takeIf { it.isNotBlank() }?.let { append("<p class=\"description\">${escape(it)}</p>") }
        endpoint.source?.let { append("<p class=\"source\">Source · ${escape(it)}</p>") }
        append("</div><div class=\"detail-body\">")
        endpoint.parameters.takeIf { it.isNotEmpty() }?.let { params ->
            append("<section class=\"section\"><h4 class=\"section-title\">Parameters <span>${params.size} fields</span></h4><div class=\"table-wrap\"><table><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Description</th></tr></thead><tbody>")
            params.forEach { p -> append("<tr><td><strong>${escape(p.name)}</strong></td><td>${escape(p.location)}</td><td class=\"${if (p.required) "required" else ""}\">${if (p.required) "Required" else "Optional"}</td><td>${escape(p.description ?: "—")}</td></tr>") }
            append("</tbody></table></div></section>")
        }
        endpoint.requestBodyJson?.let { body -> appendCodeSection("Request body", body) }
        endpoint.responseBodyJson?.let { response ->
            val body = response
            val rendered = if (wrapResponses) "{\n  \"code\": 0,\n  \"msg\": \"\",\n  \"data\": $body\n}" else body
            appendCodeSection("Response example", rendered)
        } ?: append("<section class=\"section\"><h4 class=\"section-title\">Response example</h4><p class=\"empty\">No response model detected for this endpoint.</p></section>")
        append("</div>")
    }

    private fun StringBuilder.appendCodeSection(label: String, body: String) {
        val id = "code-${length}"
        append("<section class=\"section\"><h4 class=\"section-title\">${escape(label)}</h4><div class=\"code-shell\"><div class=\"code-label\"><span>JSON</span><button class=\"copy-button\" data-copy=\"$id\" type=\"button\">Copy</button></div><pre id=\"$id\">")
        append(escape(body)).append("</pre></div></section>")
    }

    private data class PreviewItem(val id: Int, val group: String, val title: String, val method: String, val path: String, val detail: String)

    private fun folderIcon() = "<svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 7.5A2.5 2.5 0 0 1 5.5 5H10l2 2h6.5A2.5 2.5 0 0 1 21 9.5v7A2.5 2.5 0 0 1 18.5 19h-13A2.5 2.5 0 0 1 3 16.5z\"/></svg>"
    private fun searchIcon() = "<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>"
    private fun moonIcon() = "<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"><path d=\"M20.5 15.2A8.5 8.5 0 0 1 8.8 3.5 8.5 8.5 0 1 0 20.5 15.2z\"/></svg>"
    private fun escape(value: String): String = value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")
}
